# Let's examine each transformation individually
for i in range(len(inputs)):
    print(f"Example {i}: '{inputs[i]}' -> '{outputs[i]}'")

    # Manual analysis of differences
    inp = inputs[i]
    out = outputs[i]

    # Find where they differ
    min_len = min(len(inp), len(out))
    diff_pos = -1
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(out):
            diff_pos = min_len

    print(f"  Difference at position: {diff_pos}")
    if diff_pos >= 0 and diff_pos < len(out):
        if diff_pos < len(inp):
            print(f"  Character changed from '{inp[diff_pos]}' to '{out[diff_pos]}'")
        else:
            print(f"  Character added at position {diff_pos}: '{out[diff_pos]}'")
